def moving_average(xs: list[float], w: int) -> list[float]:
    if w > len(xs) or w <= 0:
        return []
    result = []
    for i in range(len(xs) - w + 1):
        window = xs[i:i + w]
        result.append(sum(window) / w)
    return result
