def caesar(s: str, k: int) -> str:
    result = []
    for ch in s:
        if 'a' <= ch <= 'z':
            shifted = (ord(ch) - ord('a') + k) % 26
            result.append(chr(ord('a') + shifted))
        elif 'A' <= ch <= 'Z':
            shifted = (ord(ch) - ord('A') + k) % 26
            result.append(chr(ord('A') + shifted))
        else:
            result.append(ch)
    return ''.join(result)
